css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .texto-box{border: 2px solid var(--bosque); border-radius: 12px; padding: 10px 12px; margin-bottom: 10px; width: 100%; box-sizing: border-box;}
.mz .texto-parrafo{font-size: 16px; font-weight: 600; line-height: 1.55;}
.mz .preguntas-lista{display: flex; flex-direction: column; gap: 7px; margin-bottom: 10px;}
.mz .pregunta-item{display: flex; flex-direction: column; gap: 2px;}
.mz .pregunta-texto{font-size: 15px; font-weight: 700;}
.mz .respuesta-linea{border-bottom: 1.5px solid var(--bosque); height: 20px; width: 100%;}
.mz .reflexion-lista{display: flex; flex-direction: column; gap: 10px; margin-bottom: 10px;}
.mz .reflexion-item{display: flex; flex-direction: column; gap: 3px;}
.mz .reflexion-pregunta{font-size: 15px; font-weight: 700;}
.mz .reflexion-lineas{display: flex; flex-direction: column; gap: 4px;}
.mz .reflexion-linea{border-bottom: 1.5px solid var(--bosque); height: 20px; width: 100%;}
.mz .emparejar-grid{display: grid; grid-template-columns: 1fr 1fr; gap: 16px; margin-bottom: 8px;}
.mz .emparejar-causas{display: flex; flex-direction: column; gap: 9px;}
.mz .emp-item{display: flex; align-items: center; gap: 5px;}
.mz .emp-n{font-size: 15px; font-weight: 700; white-space: nowrap;}
.mz .emp-texto{font-size: 14px; flex: 1; line-height: 1.3;}
.mz .emp-flecha{font-size: 15px; font-weight: 700;}
.mz .emp-respuesta{border-bottom: 1.5px solid var(--bosque); width: 28px; height: 20px; flex-shrink: 0;}
.mz .emparejar-consecuencias{display: flex; flex-direction: column; gap: 9px; border-left: 1.5px dashed #999; padding-left: 14px;}
.mz .cons-item{display: flex; gap: 6px; align-items: flex-start;}
.mz .cons-letra{font-size: 15px; font-weight: 700; white-space: nowrap;}
.mz .cons-texto{font-size: 14px; line-height: 1.3;}
.mz .cons-texto,.mz .emp-texto,.mz .texto-parrafo{line-height: 1.725 !important;}
